/* ============================================================
 * 物色集 · 内置精选数据（人工整理）
 * ------------------------------------------------------------
 * 数据原则：
 *  1. 所有引文均为真实文献原句，标注出处；
 *  2. 严格区分四个层面——
 *     aliases   词汇层：同一事物的异名（霖、银竹是雨的"名字"）
 *     emotions  情感层：意象承载的情感（雨触发离愁、羁旅……）
 *     compounds 复合意象层：意象与情境组合生成的新意境
 *              （巴山夜雨 = 雨+夜+山 → 思归，是"意境"不是"名字"）
 *     films     跨媒介层：电影对该意象的转译，含情绪功能与古典溯源；
 *  3. 生成逻辑依据《文心雕龙·物色》「物色之动，心亦摇焉」：
 *     物触发情，情反过来凝结、命名出复合意象，再流布至后世媒介。
 * ============================================================ */

